'use strict';

// MAIN //

/**
* Returns a list of 10 colors as RGB hexadecimal strings for use as a categorical scheme.
*
* @returns {Array<string>} list of colors
*
* @example
* var list = category10();
* // returns [...]
*/
function category10() {
	return [
		'#1f77b4',
		'#ff7f0e',
		'#2ca02c',
		'#d62728',
		'#9467bd',
		'#8c564b',
		'#e377c2',
		'#7f7f7f',
		'#bcdb22',
		'#17becf'
	];
}


// EXPORTS //

module.exports = category10;
